contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address target, uint256 amount) public payable {
        require(target != address(0), "zero target");
        require(target != address(this), "test contract target");
        require(target != msg.sender, "owner target");

        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;
        uint256 beforeTarget = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 beforeOwner = c.balanceOf(msg.sender); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.balanceOf(target) == beforeTarget && c.balanceOf(msg.sender) == beforeOwner);
    }
}

